import app from 'flarum/forum/app';
import GiveawayCard from '../components/GiveawayCard';
import CalendarCard from '../advent/CalendarCard';
import { calendarSummaries } from '../../common/advent';
const cache = new Map();
let pending = new Map();
let timer = 0;

/** One request per kind for every link the page shows, 20 keys at a time. */
const fetchers = {
  // The same list endpoint, query and visibility as the giveaways page.
  giveaways: keys => app.request({
    method: 'GET',
    url: app.forum.attribute('apiUrl') + '/giveaways',
    params: {
      filter: {
        slug: keys.join(',')
      }
    }
  }).then(({
    data
  }) => keys.map(key => ({
    key,
    found: data.find(g => g.slug === key) || data.find(g => String(g.id) === key) || null
  }))),
  // Only the calendar's summary: a card never carries what is behind a door.
  advent: keys => calendarSummaries(keys).then(data => keys.map(key => ({
    key,
    found: data.find(c => c.slug === key) || null
  })))
};

/**
 * A link whose giveaway or calendar does not come back (deleted, or not
 * visible to this viewer) stays a plain link.
 */
function flush() {
  const batch = pending;
  pending = new Map();
  timer = 0;
  ['giveaways', 'advent'].forEach(kind => {
    const keys = [...batch.keys()].filter(k => k.startsWith(kind + ':')).map(k => k.slice(kind.length + 1));
    for (let i = 0; i < keys.length; i += 20) {
      const chunk = keys.slice(i, i + 20);
      fetchers[kind](chunk).then(rows => rows.forEach(({
        key,
        found
      }) => batch.get(`${kind}:${key}`)(found)), () => chunk.forEach(key => batch.get(`${kind}:${key}`)(null)));
    }
  });
}
function lookup(kind, key) {
  const id = `${kind}:${key}`;
  let found = cache.get(id);
  if (!found) {
    found = new Promise(resolve => pending.set(id, resolve));
    cache.set(id, found);
    timer ||= window.setTimeout(flush, 0);
  }
  return found;
}
export default function embed(links) {
  links.forEach(([a, key, kind]) => lookup(kind, key).then(found => {
    if (!found || !a.isConnected) return;
    const holder = document.createElement('span');
    holder.className = 'GiveawayEmbed';
    a.replaceWith(holder);
    m.render(holder, kind === 'advent' ? m(CalendarCard, {
      calendar: found
    }) : m(GiveawayCard, {
      giveaway: found
    }));
  }));
}
flarum.reg.add('ernestdefoe-giveaways', 'forum/embed/embed', embed);